// Normalize legacy and current aliases into a stable freelancer-to-client email contract.
const source = ($json.query && typeof $json.query === 'object' && !Array.isArray($json.query))
  ? $json.query
  : (($json.body && typeof $json.body === 'object' && !Array.isArray($json.body))
    ? $json.body
    : ($json ?? {}));
const text = (value) => value == null ? '' : String(value).trim();
const env = typeof $env === 'object' && $env ? $env : {};
const startValue = text(source.start_time ?? source.startTime);
const parsedStart = startValue ? new Date(startValue) : null;
const timezone = text(source.timezone ?? source.time_zone) || 'Asia/Karachi';
let meetingDate = text(source.meeting_date ?? source.meetingDate ?? source.date);
let meetingTime = text(source.meeting_time ?? source.meetingTime ?? source.time);

if ((!meetingDate || !meetingTime) && parsedStart && !Number.isNaN(parsedStart.getTime()) && timezone) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(parsedStart).filter(part => part.type !== 'literal').map(part => [part.type, part.value]));
  meetingDate ||= parts.year + '-' + parts.month + '-' + parts.day;
  meetingTime ||= parts.hour + ':' + parts.minute;
}

const request = {
  host_name: text(source.host_name ?? source.hostName ?? source.freelancer_name ?? source.freelancerName ?? source.consultant_name ?? source.consultantName ?? env.FREELANCER_NAME ?? env.COMPANY_NAME) || 'Meeting Host',
  client_name: text(source.client_name ?? source.clientName ?? source.customer_name ?? source.customerName),
  host_email: text(source.host_email ?? source.hostEmail ?? source.freelancer_email ?? source.freelancerEmail).toLowerCase(),
  client_email: text(source.client_email ?? source.clientEmail ?? source.customer_email ?? source.customerEmail).toLowerCase(),
  meeting_topic: text(source.meeting_topic ?? source.meeting_title ?? source.topic ?? source.title),
  agenda: text(source.agenda ?? source.meeting_agenda ?? source.meetingAgenda ?? source.description),
  business_name: text(source.business_name ?? source.businessName),
  meeting_date: meetingDate,
  meeting_time: meetingTime,
  start_time: startValue,
  timezone,
  duration: Number(source.duration ?? source.duration_minutes ?? source.durationMinutes ?? 30),
  zoom_join_url: text(source.zoom_join_url ?? source.join_url ?? source.meetingLink),
  zoom_meeting_id: text(source.zoom_meeting_id ?? source.meeting_id ?? source.id),
  zoom_password: text(source.zoom_password ?? source.password),
  appointment_id: text(source.appointment_id ?? source.appointmentId ?? source.booking_id ?? source.bookingId),
  calendar_event_created: source.calendar_event_created === true,
  meeting_created: source.meeting_created !== false,
  email_type: text(source.email_type ?? source.emailType) || 'meeting_confirmation',
  branding: {
    company_name: text(source.company_name ?? source.companyName),
    company_website: text(source.company_website ?? source.companyWebsite),
    support_email: text(source.company_support_email ?? source.support_email ?? source.supportEmail),
    logo_url: text(source.logo_url ?? source.logoUrl),
    primary_color: text(source.primary_color ?? source.primaryColor),
    footer_text: text(source.footer_text ?? source.footerText)
  },
  attach_ics: source.attach_ics ?? source.attachIcs,
  future_actions: {
    reschedule_url: text(source.reschedule_url ?? source.rescheduleUrl),
    cancel_url: text(source.cancel_url ?? source.cancelUrl)
  }
};

const errors = [];
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailPattern.test(request.client_email)) errors.push({ field: 'client_email', message: 'A valid client_email is required.' });
for (const field of ['client_name', 'meeting_topic', 'meeting_date', 'meeting_time', 'timezone', 'zoom_join_url', 'zoom_meeting_id']) {
  if (!request[field]) errors.push({ field, message: field + ' is required.' });
}
if (!Number.isFinite(request.duration) || request.duration <= 0) errors.push({ field: 'duration', message: 'duration must be a positive number.' });
if (request.zoom_join_url && !/^https:\/\//i.test(request.zoom_join_url)) errors.push({ field: 'zoom_join_url', message: 'zoom_join_url must be an HTTPS URL.' });

return [{ json: { valid: errors.length === 0, errors, request } }];

// Resolve presentation settings and prepare a native n8n binary .ics attachment for Gmail.
const data = $('Validate Meeting Email Data').item.json.request;
const text = (value) => value == null ? '' : String(value).trim();
const env = typeof $env === 'object' && $env ? $env : {};
const primaryColorCandidate = text(data.branding.primary_color || env.PRIMARY_COLOR);
const primaryColor = /^#[0-9a-f]{6}$/i.test(primaryColorCandidate) ? primaryColorCandidate : '#2563eb';
const config = {
  company_name: text(data.branding.company_name || data.business_name || env.COMPANY_NAME) || data.host_name,
  company_website: text(data.branding.company_website || env.COMPANY_WEBSITE),
  support_email: text(data.branding.support_email || env.COMPANY_SUPPORT_EMAIL),
  logo_url: text(data.branding.logo_url || env.LOGO_URL),
  primary_color: primaryColor,
  footer_text: text(data.branding.footer_text || env.COMPANY_FOOTER_TEXT),
  attach_ics: data.attach_ics == null ? String(env.EMAIL_ATTACH_ICS ?? 'true').toLowerCase() !== 'false' : Boolean(data.attach_ics)
};

const pad = value => String(value).padStart(2, '0');
const compactUtc = date => date.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
const escapeIcs = value => String(value ?? '').replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/,/g, '\\,').replace(/;/g, '\\;');
let startLine;
let endLine;
const parsedStart = data.start_time ? new Date(data.start_time) : null;
if (parsedStart && !Number.isNaN(parsedStart.getTime())) {
  startLine = 'DTSTART:' + compactUtc(parsedStart);
  endLine = 'DTEND:' + compactUtc(new Date(parsedStart.getTime() + data.duration * 60000));
} else {
  const localStart = new Date(data.meeting_date + 'T' + data.meeting_time + ':00Z');
  const localEnd = new Date(localStart.getTime() + data.duration * 60000);
  const compactLocal = date => date.getUTCFullYear() + pad(date.getUTCMonth() + 1) + pad(date.getUTCDate()) + 'T' + pad(date.getUTCHours()) + pad(date.getUTCMinutes()) + pad(date.getUTCSeconds());
  startLine = 'DTSTART;TZID=' + data.timezone + ':' + compactLocal(localStart);
  endLine = 'DTEND;TZID=' + data.timezone + ':' + compactLocal(localEnd);
}
const uidDomain = config.company_website ? config.company_website.replace(/^https?:\/\//, '').split('/')[0] : 'meeting.local';
const organizer = data.host_email ? 'ORGANIZER;CN=' + escapeIcs(data.host_name) + ':mailto:' + escapeIcs(data.host_email) : '';
const ics = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//' + escapeIcs(config.company_name) + '//Meeting Confirmation//EN',
  'CALSCALE:GREGORIAN',
  'METHOD:REQUEST',
  'BEGIN:VEVENT',
  'UID:' + escapeIcs(data.appointment_id || data.zoom_meeting_id) + '@' + escapeIcs(uidDomain),
  'DTSTAMP:' + compactUtc(new Date()),
  startLine,
  endLine,
  organizer,
  'ATTENDEE;CN=' + escapeIcs(data.client_name) + ';RSVP=TRUE:mailto:' + escapeIcs(data.client_email),
  'SUMMARY:' + escapeIcs(data.meeting_topic),
  'DESCRIPTION:' + escapeIcs((data.agenda || data.meeting_topic) + '\n\nJoin Zoom: ' + data.zoom_join_url),
  'LOCATION:' + escapeIcs(data.zoom_join_url),
  'URL:' + escapeIcs(data.zoom_join_url),
  'STATUS:CONFIRMED',
  'END:VEVENT',
  'END:VCALENDAR'
].filter(Boolean).join('\r\n');
const filename = 'meeting-' + data.zoom_meeting_id.replace(/[^a-z0-9_-]/gi, '-') + '.ics';
const contentBase64 = Buffer.from(ics, 'utf8').toString('base64');

return [{
  json: {
    data,
    config,
    generated_at: new Date().toISOString(),
    calendar_attachment: {
      binary_property: 'calendar_invite',
      filename,
      content_type: 'text/calendar; charset=utf-8; method=REQUEST',
      content_base64: contentBase64
    }
  },
  binary: {
    calendar_invite: {
      data: contentBase64,
      mimeType: 'text/calendar',
      fileName: filename,
      fileExtension: 'ics'
    }
  }
}];

// Build one friendly, professional email from the freelancer to the client.
const input = $input.item;
const prepared = input.json;
const { data, config } = prepared;
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const preserveLines = value => escapeHtml(value).replace(/\r?\n/g, '<br>');
const safeUrl = value => /^https:\/\//i.test(String(value ?? '')) ? escapeHtml(value) : '';
const displayDate = /^\d{4}-\d{2}-\d{2}$/.test(data.meeting_date)
  ? new Intl.DateTimeFormat('en-US', { dateStyle: 'full', timeZone: 'UTC' }).format(new Date(data.meeting_date + 'T00:00:00Z'))
  : data.meeting_date;
const discussionText = data.agenda || ('We’ll use our time to discuss ' + data.meeting_topic + ', answer your questions, and agree on the best next steps.');

const detailRow = (label, value) => value === '' || value == null
  ? ''
  : '<tr><td style="padding:8px 0;color:#64748b;width:40%;font-size:14px;">' + escapeHtml(label) + '</td><td style="padding:8px 0;color:#0f172a;font-weight:600;font-size:14px;">' + escapeHtml(value) + '</td></tr>';
const brand = () => {
  const logo = config.logo_url && safeUrl(config.logo_url) ? '<img src="' + safeUrl(config.logo_url) + '" width="132" alt="' + escapeHtml(config.company_name) + '" style="display:block;max-width:132px;height:auto;border:0;">' : '';
  return '<tr><td style="padding:24px 38px;background:#ffffff;border-bottom:1px solid #e2e8f0;">' + (logo || '<div style="font-size:18px;font-weight:800;color:#0f172a;">' + escapeHtml(config.company_name) + '</div>') + '</td></tr>';
};
const meetingCard = '<div style="border:1px solid #dbe4f0;border-radius:12px;padding:20px 22px;margin:24px 0;background:#ffffff;"><div style="font-size:19px;font-weight:800;color:#0f172a;margin-bottom:10px;">' + escapeHtml(data.meeting_topic) + '</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0">' +
  detailRow('Date', displayDate) +
  detailRow('Time', data.meeting_time + ' (' + data.timezone + ')') +
  detailRow('Duration', data.duration + ' minutes') +
  detailRow('With', data.host_name) +
  detailRow('Meeting ID', data.zoom_meeting_id) +
  detailRow('Password', data.zoom_password) +
  '</table></div>';
const joinSection = '<table role="presentation" cellspacing="0" cellpadding="0" style="margin:0 0 18px;"><tr><td><a href="' + safeUrl(data.zoom_join_url) + '" style="display:inline-block;padding:14px 24px;border-radius:9px;text-decoration:none;font-size:15px;font-weight:700;background:' + escapeHtml(config.primary_color) + ';color:#ffffff;">Join Zoom Meeting</a></td></tr></table><p style="margin:0 0 24px;font-size:13px;line-height:1.6;color:#64748b;word-break:break-all;">If the button does not work, copy this link:<br><a href="' + safeUrl(data.zoom_join_url) + '" style="color:' + escapeHtml(config.primary_color) + ';">' + escapeHtml(data.zoom_join_url) + '</a></p>';
const discussion = '<div style="padding:19px 20px;background:#f8fafc;border-radius:11px;border-left:4px solid ' + escapeHtml(config.primary_color) + ';margin:0 0 24px;"><div style="font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:#64748b;margin-bottom:8px;">What we’ll discuss</div><div style="font-size:15px;line-height:1.7;color:#334155;">' + preserveLines(discussionText) + '</div></div>';
const footer = () => {
  const support = config.support_email ? ' Need help? <a href="mailto:' + escapeHtml(config.support_email) + '" style="color:#cbd5e1;">' + escapeHtml(config.support_email) + '</a>.' : '';
  const website = config.company_website && safeUrl(config.company_website) ? '<a href="' + safeUrl(config.company_website) + '" style="color:#cbd5e1;">' + escapeHtml(config.company_name) + '</a>' : escapeHtml(config.company_name);
  return (config.footer_text ? escapeHtml(config.footer_text) + '<br>' : '') + website + '.' + support;
};
const content = '<div style="font-size:12px;font-weight:800;letter-spacing:.11em;text-transform:uppercase;color:' + escapeHtml(config.primary_color) + ';margin-bottom:15px;">Meeting confirmed</div><h1 style="margin:0 0 14px;font-size:29px;line-height:1.25;">I’m looking forward to speaking with you</h1><p style="margin:0 0 12px;font-size:16px;line-height:1.7;color:#475569;">Hi ' + escapeHtml(data.client_name) + ',</p><p style="margin:0 0 20px;font-size:16px;line-height:1.7;color:#475569;">Thanks for scheduling time with me. Your meeting is confirmed, and I’m looking forward to a useful conversation about <strong>' + escapeHtml(data.meeting_topic) + '</strong>.</p>' + discussion + meetingCard + joinSection + '<div style="padding:17px 19px;background:#eff6ff;border-radius:10px;color:#1e3a8a;font-size:14px;line-height:1.65;"><strong>A quick reminder</strong><br>Please keep this email handy and join a few minutes early. The calendar invitation is attached for convenience.</div><p style="margin:26px 0 0;font-size:15px;line-height:1.7;color:#475569;">See you soon,<br><strong style="color:#0f172a;">' + escapeHtml(data.host_name) + '</strong></p>';
const html = '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>@media only screen and (max-width:620px){.shell{width:100%!important}.body{padding:28px 20px!important}.join a{display:block!important;text-align:center!important}}</style></head><body style="margin:0;padding:0;background:#eef2f7;font-family:Inter,Arial,Helvetica,sans-serif;color:#0f172a;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#eef2f7;padding:30px 12px;"><tr><td align="center"><table role="presentation" class="shell" width="620" cellspacing="0" cellpadding="0" style="width:100%;max-width:620px;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 12px 36px rgba(15,23,42,.10);"><tr><td style="height:7px;background:' + escapeHtml(config.primary_color) + ';"></td></tr>' + brand() + '<tr><td class="body" style="padding:38px 42px;">' + content + '</td></tr><tr><td style="padding:23px 38px;background:#0f172a;color:#94a3b8;font-size:12px;line-height:1.7;text-align:center;">' + footer() + '</td></tr></table></td></tr></table></body></html>';

return [{
  json: {
    ...prepared,
    client_template: {
      subject: 'Your Meeting is Confirmed 🎉',
      html
    },
    template_version: '4.0.0-gmail-freelancer',
    email_provider: 'gmail'
  },
  binary: input.binary
}];

// Expose the message fields consumed by the native n8n Gmail node.
const input = $input.item;
const prepared = input.json;
return [{
  json: {
    ...prepared,
    client_email_message: {
      sender_name: prepared.data.host_name,
      recipient: prepared.data.client_email,
      subject: prepared.client_template.subject,
      html: prepared.client_template.html,
      attachment_binary_property: prepared.config.attach_ics ? prepared.calendar_attachment.binary_property : '',
      prepared_at: prepared.generated_at
    }
  },
  binary: input.binary
}];

// Normalize the native Gmail response without failing the completed meeting.
const response = $json ?? {};
const prepared = $('Prepare Client Gmail Message').item.json;
const completedAt = new Date();
const startedAt = new Date(prepared.client_email_message.prepared_at);
const gmailError = response.error?.message ?? response.error ?? '';
const sent = !gmailError && Boolean(response.id || response.threadId);
const client = {
  sent,
  provider: 'gmail',
  sender: 'authenticated freelancer Gmail account',
  sender_name: prepared.client_email_message.sender_name,
  recipient: prepared.client_email_message.recipient,
  status_code: sent ? 200 : 500,
  provider_message_id: String(response.id ?? ''),
  thread_id: String(response.threadId ?? ''),
  error: sent ? null : String(gmailError || 'Gmail did not return a message ID. Check the Gmail credential and execution details.'),
  provider_response: response,
  prepared_at: prepared.client_email_message.prepared_at,
  completed_at: completedAt.toISOString(),
  elapsed_ms_since_preparation: Number.isNaN(startedAt.getTime()) ? null : completedAt.getTime() - startedAt.getTime(),
  execution_id: typeof $execution !== 'undefined' ? $execution.id : null,
  calendar_attachment_sent: sent && prepared.config.attach_ics
};
if (!sent) console.error('Gmail meeting confirmation failed', { recipient_type: 'client', ...client, timestamp: completedAt.toISOString() });
const failures = sent ? [] : [{
  recipient: 'client',
  email: client.recipient,
  error: client.error,
  status_code: client.status_code,
  timestamp: client.completed_at,
  provider_response: client.provider_response
}];

return [{ json: {
  success: true,
  meeting_created: prepared.data.meeting_created,
  calendar_event_created: prepared.data.calendar_event_created,
  host_email_sent: false,
  host_email_skipped: true,
  client_email_sent: sent,
  email_sender: 'authenticated freelancer Gmail account',
  email_recipient: prepared.data.client_email,
  zoom_join_url: prepared.data.zoom_join_url,
  meeting_id: prepared.data.zoom_meeting_id,
  message: sent
    ? 'Meeting created successfully and the client confirmation was sent from the freelancer Gmail account.'
    : 'Meeting created successfully, but the client Gmail confirmation failed.',
  email_failures: failures,
  email_results: { client },
  email_template_version: prepared.template_version,
  calendar_attachment_prepared: Boolean(prepared.calendar_attachment?.content_base64),
  calendar_attachment_sent: client.calendar_attachment_sent,
  completed_at: completedAt.toISOString()
} }];
